def assign_benchmark_customers(apps, schema_editor):
    database = schema_editor.connection.alias
    Customer = apps.get_model("core", "Customer")
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    assignments = (
        ("Retailer A", "sales-a"),
        ("Distributor B", "sales-b"),
    )
    for customer_name, username in assignments:
        user = User.objects.using(database).filter(username=username).first()
        customer = Customer.objects.using(database).filter(
            name=customer_name,
            assigned_salesman_id=None,
        ).first()
        if user and customer:
            customer.assigned_salesman_id = user.pk
            customer.save(update_fields=["assigned_salesman"])


